SELECT item_id FROM (
    SELECT item_id, max(ts) AS last_ts FROM user_behavior
    WHERE user_id=#{userId}
        AND (action IN ('CLICK','LIKE','PLAY') OR (action='RATING' AND value>=4))
    GROUP BY item_id
) s ORDER BY last_ts DESC LIMIT #{limit}

SELECT item_id FROM user_behavior WHERE user_id=#{userId}
AND ((action='RATING' AND value>=4) OR action IN ('CLICK','LIKE','PLAY'))
ORDER BY ts DESC LIMIT #{limit}
